// sha1: the SHA-1 digest (FIPS 180-4) of 4 MiB of generated bytes: blocks
// of 64 bytes, an 80-word schedule and 80 rounds each.
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>

static uint32_t rotl(uint32_t x, int r) { return x << r | x >> (32 - r); }

int main(void) {
    int64_t n = 1 << 22, len = n + 64;
    uint8_t *msg = calloc(len, 1);
    for (int64_t i = 0; i < n; i++) msg[i] = (uint8_t)((i * 2654435761) >> 13 & 255);
    msg[n] = 128;
    uint64_t bits = (uint64_t)n * 8;
    for (int i = 0; i < 8; i++) msg[n + 56 + i] = (uint8_t)(bits >> (56 - 8 * i));
    uint32_t h[5] = {0x67452301, 0xEFCDAB89, 0x98BADCFE, 0x10325476, 0xC3D2E1F0};
    for (int64_t off = 0; off < len; off += 64) {
        uint32_t w[80];
        for (int t = 0; t < 16; t++) {
            const uint8_t *p = msg + off + 4 * t;
            w[t] = (uint32_t)p[0] << 24 | (uint32_t)p[1] << 16 | (uint32_t)p[2] << 8 | p[3];
        }
        for (int t = 16; t < 80; t++) w[t] = rotl(w[t - 3] ^ w[t - 8] ^ w[t - 14] ^ w[t - 16], 1);
        uint32_t a = h[0], b = h[1], c = h[2], d = h[3], e = h[4];
        for (int t = 0; t < 80; t++) {
            uint32_t f, k;
            if (t < 20) { f = (b & c) | (~b & d); k = 0x5A827999; }
            else if (t < 40) { f = b ^ c ^ d; k = 0x6ED9EBA1; }
            else if (t < 60) { f = (b & c) | (b & d) | (c & d); k = 0x8F1BBCDC; }
            else { f = b ^ c ^ d; k = 0xCA62C1D6; }
            uint32_t tmp = rotl(a, 5) + f + e + k + w[t];
            e = d;
            d = c;
            c = rotl(b, 30);
            b = a;
            a = tmp;
        }
        h[0] += a;
        h[1] += b;
        h[2] += c;
        h[3] += d;
        h[4] += e;
    }
    for (int i = 0; i < 5; i++) printf("%08x", h[i]);
    printf("\n");
    return 0;
}
